INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT146-S3-Q6$batch10$, 146, 3, 6, $batch10$Principle-Strengthen$batch10$, $batch10$The decisions that one makes can profoundly affect one’s life years later. So one should not regret the missed opportunities of youth, for had one decided instead to seize one of these opportunities, one would not have some of the close personal relationships one currently has. And everyone deeply cherishes their close personal relationships.$batch10$, $batch10$Which one of the following principles, if valid, most helps to justify the reasoning in the argument?$batch10$, $batch10$B$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=146 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT146-S3-Q6$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$One should not regret making a decision unless a different decision would have resulted in one having a greater number of close personal relationships.$batch10$, $batch10$Doesn't Apply$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT146-S3-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$One should not regret making a decision if it helped to bring about something that one cherishes.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT146-S3-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$One should not regret making a decision that had little effect on one’s life.$batch10$, $batch10$Opposite$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT146-S3-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$People who regret the missed opportunities of youth should cherish their close personal relationships more deeply.$batch10$, $batch10$Wrong Conclusion$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT146-S3-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$People with few close personal relationships should cherish the ones they have.$batch10$, $batch10$Out of Scope$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT146-S3-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT146-S3-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$One should not regret the missed opportunities of youth.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$Had one seized those opportunities, one wouldn't have some of one's current close relationships. Everyone deeply cherishes their close relationships.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$Passing up those opportunities helped bring about relationships one cherishes. The principle has to say that a decision that helped bring about something one cherishes is not one to regret.$batch10$), (3, $batch10$Goal$batch10$, $batch10$One should not regret a decision that helped bring about something one cherishes.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT146-S3-Q6$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This condition turns on whether a different decision would have produced more close relationships. The argument says a different decision would have meant losing some current ones, not that it would have produced more or fewer overall.$batch10$), ($batch10$B$batch10$, $batch10$Not seizing the opportunities helped bring about relationships one cherishes. This principle says not to regret a decision like that, which gives the conclusion.$batch10$), ($batch10$C$batch10$, $batch10$The argument opens by saying decisions can profoundly affect one's life. Missing those opportunities had a big effect, so this principle doesn't apply.$batch10$), ($batch10$D$batch10$, $batch10$This tells people who have regrets to cherish their relationships more. The conclusion is that one shouldn't have the regrets in the first place.$batch10$), ($batch10$E$batch10$, $batch10$People with few relationships aren't the subject. The argument is about regret.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT146-S3-Q6$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
